package io.github.abyxs.codingremote.tests;
import android.app.*;import android.content.*;import android.os.*;import android.view.*;import android.widget.*;import android.view.accessibility.AccessibilityNodeInfo;import org.json.*;import java.lang.reflect.*;import java.util.*;

/** All API calls use synthetic data on a dedicated emulator. */
public final class PluginRegression extends Instrumentation {
    interface Check{void run()throws Exception;}Activity app;final ArrayList<String> reads=new ArrayList<>();final ArrayList<JSONObject> writes=new ArrayList<>();
    Object get(Object o,String n)throws Exception{Field f=o.getClass().getDeclaredField(n);f.setAccessible(true);return f.get(o);}void set(Object o,String n,Object v)throws Exception{Field f=o.getClass().getDeclaredField(n);f.setAccessible(true);f.set(o,v);}Object call(Object o,String n,Class[] types,Object...args)throws Exception{Class<?> type=o instanceof Class?(Class)o:o.getClass();Method m=type.getDeclaredMethod(n,types);m.setAccessible(true);return m.invoke(o instanceof Class?null:o,args);}
    void require(boolean value,String why){if(!value)throw new AssertionError(why);}void ui(Check c)throws Exception{Throwable[] e={null};runOnMainSync(()->{try{c.run();}catch(Throwable x){e[0]=x;}});if(e[0]!=null)throw new Exception(e[0]);waitForIdleSync();}void await(Check c)throws Exception{Throwable last=null;for(int i=0;i<90;i++){try{c.run();return;}catch(Throwable e){last=e;}SystemClock.sleep(100);}throw new Exception(last);}
    View find(View v,String label){if(v instanceof TextView&&label.equals(((TextView)v).getText().toString())||label.equals(String.valueOf(v.getContentDescription())))return v;if(v instanceof ViewGroup)for(int i=0;i<((ViewGroup)v).getChildCount();i++){View found=find(((ViewGroup)v).getChildAt(i),label);if(found!=null)return found;}return null;}
    AccessibilityNodeInfo node(AccessibilityNodeInfo v,String label){if(v==null)return null;if(label.equals(String.valueOf(v.getText()))||label.equals(String.valueOf(v.getContentDescription())))return v;for(int i=0;i<v.getChildCount();i++){AccessibilityNodeInfo n=node(v.getChild(i),label);if(n!=null)return n;}return null;}
    void click(String label)throws Exception{await(()->ui(()->{View v=find(app.getWindow().getDecorView(),label);require(v!=null,"visible "+label);v.performClick();}));}
    void swipe(float x,float y,float endX,float endY)throws Exception{long start=SystemClock.uptimeMillis();for(int i=0;i<=16;i++){int action=i==0?0:i==16?1:2;MotionEvent e=MotionEvent.obtain(start,SystemClock.uptimeMillis(),action,x+(endX-x)*i/16f,y+(endY-y)*i/16f,0);sendPointerSync(e);e.recycle();SystemClock.sleep(18);}waitForIdleSync();}
    void shot(String name)throws Exception{SystemClock.sleep(350);android.graphics.Bitmap b=getUiAutomation().takeScreenshot();java.io.File d=new java.io.File(getTargetContext().getExternalFilesDir(null),"ui-captures");d.mkdirs();try(java.io.FileOutputStream out=new java.io.FileOutputStream(new java.io.File(d,name+".png"))){b.compress(android.graphics.Bitmap.CompressFormat.PNG,100,out);}b.recycle();}
    public void onCreate(Bundle b){super.onCreate(b);start();}
    public void onStart(){Bundle result=new Bundle();try{
        Context c=getTargetContext();for(String pref:new String[]{"coding-remote","pending","composer-plugins"})c.getSharedPreferences(pref,0).edit().clear().commit();c.getSharedPreferences("ui",0).edit().putBoolean("overlay",false).putBoolean("notifications",false).putBoolean("resumeChat",false).commit();
        c.getSharedPreferences("composer-plugins",0).edit().putStringSet("https://fixture.trycloudflare.com|codex:fixture",new HashSet<>(Arrays.asList("old-nature-reader"))).commit();
        app=startActivitySync(new Intent().setClassName(c,"io.github.abyxs.codingremote.MainActivity").addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));
        JSONObject session=new JSONObject().put("id","fixture").put("title","插件与模式测试").put("model","model-a").put("effort","high").put("status","idle").put("requests",new JSONArray());
        JSONObject catalog=new JSONObject().put("currentMode","default").put("currentModel","model-a").put("models",new JSONArray()).put("modes",new JSONArray().put(new JSONObject().put("id","default").put("name","普通模式")).put(new JSONObject().put("id","plan").put("name","计划模式")).put(new JSONObject().put("id","goal").put("name","目标模式"))).put("skills",new JSONArray().put(new JSONObject().put("id","plugin:nature-skills@nature-skills").put("displayName","Nature Skills").put("kind","plugin").put("memberIds",new JSONArray().put("old-nature-reader").put("old-nature-writer"))).put(new JSONObject().put("id","plugin:documents@openai-primary-runtime").put("displayName","Documents").put("kind","plugin")).put(new JSONObject().put("id","installed:browser").put("displayName","Browser").put("selectable",false).put("status","运行中")));
        Class<?> transport=Class.forName("io.github.abyxs.codingremote.MainActivity$Transport");Object mock=Proxy.newProxyInstance(transport.getClassLoader(),new Class[]{transport},(o,m,args)->{String path=((String)args[2]).split("\\?",2)[0];JSONObject body=(JSONObject)args[3];synchronized(catalog){if(body!=null)writes.add(new JSONObject(body.toString()).put("route",path));if(path.endsWith("/catalog"))return new JSONObject(catalog.toString());if(path.endsWith("/settings")){catalog.put("currentMode",body.optString("collaborationMode"));return new JSONObject().put("status","accepted");}if(body!=null)return new JSONObject().put("status","accepted");return new JSONObject().put("connected",true).put("session",session).put("messages",new JSONArray());}});
        ui(()->{set(app,"transport",mock);set(app,"origin","https://fixture.trycloudflare.com");set(app,"token","fixture");set(app,"backend","codex");call(app,"openSession",new Class[]{String.class,String.class},"fixture","插件与模式测试");});SystemClock.sleep(400);
        ui(()->call(app,"toggleCatalog",new Class[]{String.class},"plugins"));await(()->ui(()->require(find((View)get(app,"inlineOptions"),"Nature Skills")!=null,"package menu loaded")));
        ui(()->{View panel=(View)get(app,"inlineOptions");require(find(panel,"计划模式")!=null&&find(panel,"目标模式")!=null,"real modes visible in plugin menu");require(find(panel,"Browser · 运行中") instanceof TextView&&!(find(panel,"Browser · 运行中") instanceof CheckBox),"runtime plugin status is not a false toggle");require(count(panel,"Nature Skills")==1,"Nature package appears once");CheckBox nature=(CheckBox)find(panel,"Nature Skills");if(!nature.isChecked())nature.performClick();});click("Documents");shot("208-plugin-packages");
        ui(()->{call(app,"closeOptions",new Class[]{});((EditText)get(app,"composer")).setText("插件回归测试");((Button)get(app,"sendButton")).performClick();});idle();require(writes.stream().anyMatch(w->w.optString("route").endsWith("/send")&&w.optJSONArray("plugins").toString().contains("plugin:nature-skills@nature-skills")&&w.optJSONArray("plugins").toString().contains("plugin:documents@openai-primary-runtime")&&!w.optJSONArray("plugins").toString().contains("old-nature")),"send uses package ids not individual skills");
        ui(()->call(app,"toggleCatalog",new Class[]{String.class},"plugins"));click("计划模式");idle();require(writes.stream().anyMatch(w->w.optString("collaborationMode").equals("plan")),"plan selection reaches settings API");ui(()->call(app,"toggleCatalog",new Class[]{String.class},"plugins"));click("目标模式");await(()->require(node(getUiAutomation().getRootInActiveWindow(),"设置目标模式")!=null,"goal opens objective entry rather than plugin checkbox"));shot("208-goal-mode");sendKeyDownUpSync(KeyEvent.KEYCODE_BACK);
        result.putString("stream","PASS: package-level plugins, document plugins, read-only runtime status, package send ids, plan settings and explicit goal entry.\n");finish(Activity.RESULT_OK,result);
    }catch(Throwable e){result.putString("stream","FAIL: "+android.util.Log.getStackTraceString(e));finish(Activity.RESULT_CANCELED,result);}finally{try{if(app!=null)ui(()->app.finish());}catch(Exception ignored){}}}
    int count(View view,String text){int n=view instanceof TextView&&((TextView)view).getText().toString().equals(text)?1:0;if(view instanceof ViewGroup)for(int i=0;i<((ViewGroup)view).getChildCount();i++)n+=count(((ViewGroup)view).getChildAt(i),text);return n;}
    void idle()throws Exception{await(()->ui(()->require(!(Boolean)get(app,"sending")&&get(app,"pending")==null,"request completed")));}
}
